arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1950_02.json') as f:
    data = json.load(f)

# Print keys at top level
def print_structure(d, indent=0):
    if isinstance(d, dict):
        for k, v in d.items():
            print(' ' * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 2:
                print_structure(v, indent + 2)
    elif isinstance(d, list) and len(d) > 0 and indent < 2:
        print(' ' * indent + f'List of {len(d)} items')
        if isinstance(d[0], dict):
            print(' ' * indent + 'First item keys: ' + str(list(d[0].keys())[:5]))

print_structure(data)
"
